// Merge auto-generated icons with custom ones. Custom ones take priority.
export const CHAT_ICONS: Record<string, string> = {
  ...autoIcons,
  ...customIcons,
}

export function findIcon(name: string): string | null {
  const exact = CHAT_ICONS[name]
  if (exact) return exact
  const key = Object.keys(CHAT_ICONS).find(k => k.includes(name))
  return key ? CHAT_ICONS[key] : null
}

export function replaceIcons(text: string): string {
  return text.replace(/:metrys-([\w-]+):/g, (_, name) => {
    const icon = findIcon(`metrys-${name}`)
    return icon || `:${name}:`
  })
}

